#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

void typeSlowly(const String &s, int ms = 3) {
  for (size_t i = 0; i < s.length(); i++) { Keyboard.print(s[i]); delay(ms); }
}

void setup() {
  USB.begin();
  Keyboard.begin();
  delay(4000);

  // Win + R → cmd
  Keyboard.press(KEY_LEFT_GUI); Keyboard.press('r');
  delay(100); Keyboard.releaseAll();
  delay(1500);
  typeSlowly("cmd", 10);
  Keyboard.press(KEY_RETURN); Keyboard.releaseAll();
  delay(2500);

  // Создаём HTML + открываем в браузере
  String cmd =
    "powershell -NoProfile -Command \""
    "[IO.File]::WriteAllText($env:TEMP+'\\v.html','<html><body style=''margin:0;background:#000''>"
    "<video id=''v'' src=''https://cdn.jsdelivr.net/gh/tttimirtt-spec/prank@main/main.mp4'' "
    "autoplay muted controls style=''width:100vw;height:100vh''></video>"
    "<script>var v=document.getElementById(''v'');v.volume=0.85;"
    "document.addEventListener(''keydown'',function(){v.muted=false;v.play();},{once:true});</script>"
    "</body></html>');"
    "Start-Process ($env:TEMP+'\\v.html');exit"
    "\"";


  typeSlowly(cmd, 3);
  delay(300);
  Keyboard.press(KEY_RETURN); Keyboard.releaseAll();

  // Ждём, пока браузер откроется и видео начнёт играть (muted)
  delay(5000);

  // Жмём 'x' → keydown → JS снимает muted, ставит 85%, play()
  Keyboard.press('x'); delay(50); Keyboard.releaseAll();
  delay(500);

  // F11 → fullscreen
  Keyboard.press(KEY_F11); delay(50); Keyboard.releaseAll();
}

void loop() {}
